USE pet_adoption_network;
DROP PROCEDURE IF EXISTS Approve_Adoption; DROP PROCEDURE IF EXISTS Generate_Overdue_Medical_Alerts; DROP PROCEDURE IF EXISTS Animal_Availability_Report;
DELIMITER $$
CREATE PROCEDURE Approve_Adoption(IN p_id INT) BEGIN DECLARE v_animal INT; DECLARE v_adopter INT; DECLARE v_status VARCHAR(30); DECLARE v_visit VARCHAR(30); DECLARE v_rec VARCHAR(30); DECLARE v_count INT DEFAULT 0; START TRANSACTION; SELECT animal_id,adopter_id,application_status INTO v_animal,v_adopter,v_status FROM adoption_applications WHERE application_id=p_id FOR UPDATE; IF v_status IS NULL OR v_status<>'Approved' THEN ROLLBACK; SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Application is not approved'; END IF; SELECT visit_status,approval_recommendation INTO v_visit,v_rec FROM home_visits WHERE application_id=p_id ORDER BY visit_id DESC LIMIT 1; IF v_visit<>'Completed' OR v_rec<>'Recommended' THEN ROLLBACK; SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Completed and recommended home visit required'; END IF; SELECT COUNT(*) INTO v_count FROM adoption_records WHERE animal_id=v_animal AND adoption_status='Completed'; IF v_count>0 THEN ROLLBACK; SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Animal is already adopted'; END IF; INSERT INTO adoption_records(animal_id,adopter_id,application_id,adoption_status) VALUES(v_animal,v_adopter,p_id,'Completed'); COMMIT; END$$
CREATE PROCEDURE Generate_Overdue_Medical_Alerts() BEGIN INSERT IGNORE INTO medical_followup_alerts(medical_id,remarks) SELECT medical_id,'Generated by overdue-check procedure' FROM medical_records WHERE next_checkup_date<CURRENT_DATE AND follow_up_status='Pending'; SELECT ROW_COUNT() new_alerts_created; END$$
CREATE PROCEDURE Animal_Availability_Report() BEGIN SELECT * FROM Available_Animals_View ORDER BY species,size,name; END$$
DELIMITER ;
